sc = spark.sparkContext
get_probability = F.udf(lambda v: float(v[1]), FloatType())

import sys

sys.path.insert(0, "./recommendation_system/script/")
from support_function import *

today = getConfig("core", "today")
today = datetime.strptime(today, "%Y-%m-%d")

from pyspark.sql.functions import PandasUDFType, pandas_udf

schema = StructType(
    [
        StructField("cif_number", StringType()),
        StructField("product", StringType()),
        StructField("probability", DoubleType()),
    ]
)


@pandas_udf(schema, functionType=PandasUDFType.GROUPED_MAP)
def get_recommended_product(df):
    cif_number = df.loc[0, "cif_number"]
    df = df.set_index("cif_number").transpose()
    df = df.sort_values(df.columns[0], ascending=False)
    df = df.reset_index()
    df.columns = ["product", "probability"]
    df["cif_number"] = cif_number
    return df


queries = "SELECT * FROM mldb.mii_rs_tf_product_portfolio"
dataset = spark.sql(
    queries
)  # OPEN / TO BE VALIDATED: Unity Catalog names for mldb.mii_rs_tf_product_portfolio (K7 tables, K4-TBL-004)

product = [
    c
    for c in dataset.columns
    if c not in ["partition_date", "cif_number", "training_date"]
]

for p in product:
    dataset = dataset.withColumn(p, F.when(F.col(p) > 0, F.lit(1)).otherwise(F.col(p)))

year = 2015
dataset = dataset.withColumn(
    "year", F.split("partition_date", "-").getItem(0).cast("int") - year
)
dataset = dataset.withColumn(
    "month", F.split("partition_date", "-").getItem(1).cast("int")
)
dataset = dataset.withColumn(
    "partition_month",
    F.concat(F.col("year") + F.lit(year), F.lit("-"), F.col("month"), F.lit("-1")),
)
dataset = dataset.withColumn("month_int", (F.col("month") + 12 * F.col("year")))

max_month_int = (
    dataset.select(F.max("month_int").alias("max_month_int")).collect()[0].max_month_int
)

queries = "SELECT * FROM mldb.mii_rs_master_customers"
df_details = spark.sql(
    queries
)  # OPEN / TO BE VALIDATED: Unity Catalog names for mldb.mii_rs_master_customers (K7 tables, K4-TBL-004)
df_details = df_details.filter(F.col("active_flag") == 1)
df_details = df_details.repartition("cif_number")

fpath = getConfig("prediction", "fe_fpath", sc)
fe_model = PipelineModel.load(fpath)
df_details = fe_model.transform(df_details)

df_details = df_details.withColumn(
    "new_customers",
    F.when(
        F.months_between(F.lit(today), F.col("cif_creation_date")) < 7, F.lit(1)
    ).otherwise(0),
)

coln = "cif_creation_date"
df_details = df_details.withColumn(
    "join_month", F.split(coln, "-").getItem(1).cast("int")
)
df_details = df_details.withColumn(
    "join_day", F.split(coln, "-").getItem(2).cast("int")
)

exclude_cols = [
    "cif_creation_date",
    "cif_number",
    "partition_date",
    "partition_month",
    "training_date",
    "sum_idr_balance_amount",
    "month_int",
    "year",
]
categorical_cols = [
    t[0] for t in df_details.dtypes if t[1] == "string" and t[0] not in exclude_cols
]
numerical_cols = ["age"]

sel_cols = [
    "cif_number",
    "new_customers",
    "join_month",
    "join_day",
    "flag_simobi",
    "payroll_flag",
    "active_flag",
]
sel_cols += [c + "Scaled" for c in numerical_cols] + [
    c + "ClassVec" for c in categorical_cols
]
dataset = dataset.repartition("cif_number")
dataset = dataset.join(df_details[sel_cols], on="cif_number", how="inner")

w = Window().partitionBy("cif_number", "month").orderBy(F.desc("partition_date"))
dataset = (
    dataset.withColumn("rn", F.row_number().over(w)).where(F.col("rn") == 1).drop("rn")
)

diff_conds = []
w = Window().partitionBy("cif_number").orderBy("month_int")
shift_val = 1
name = "id_shift_" + str(shift_val)
dataset = dataset.withColumn(name, F.lag("cif_number", count=shift_val).over(w))
dataset = dataset.withColumn(
    name, F.when(F.col(name).isNull(), 0).otherwise(F.col(name))
)
diff_cond = "diff_cond_" + str(shift_val)
diff_conds.append(diff_cond)
dataset = dataset.withColumn(
    diff_cond, F.when(F.col("cif_number") == F.col(name), F.lit(0)).otherwise(1)
)
dataset = dataset.drop(name)

for p in product:
    name = p + "_s_" + str(shift_val)
    dataset = dataset.withColumn(name, F.lag(p, count=shift_val).over(w))
    diff_cond = "diff_cond_" + str(shift_val)
    dataset = dataset.withColumn(
        name, F.when(F.col(diff_cond) == 1, F.lit(0)).otherwise(F.col(name))
    )
    dataset = dataset.withColumn(p, F.col(p) - F.col(p + "_s_1"))
    dataset = dataset.withColumn(p, F.when(F.col(p) > 0, F.lit(1)).otherwise(0))

expresion = "+".join(product)
dataset = dataset.withColumn("sum_prod", F.expr(expresion))
dataset = dataset.filter(F.col("sum_prod") != 0)
dataset = dataset.drop("sum_prod")

dataset = dataset.drop(*diff_conds)
dataset = dataset.drop_duplicates()

w = Window().partitionBy("cif_number").orderBy(F.desc("partition_date"))
dataset = (
    dataset.withColumn("rn", F.row_number().over(w)).where(F.col("rn") == 1).drop("rn")
)

dataset = dataset.fillna(0)

# load model summary
training_date = getConfig("prediction", "training_date")
queries = "SELECT * FROM mldb.mii_rs_model_summary"
model_summary = spark.sql(
    queries
)  # OPEN / TO BE VALIDATED: Unity Catalog names for mldb.mii_rs_model_summary (K7 tables, K4-TBL-004)
if training_date is None:
    training_date = (
        model_summary.select(F.max("training_date").alias("max_training_date"))
        .collect()[0]
        .max_training_date
    )

model_summary = model_summary.filter(F.col("training_date") == training_date)
try:
    best_model = (
        model_summary.filter(F.col("best_model") == "yes")
        .select("model")
        .collect()[0]
        .model
    )
except:
    max_score = (
        model_summary.select(F.max("test_f1").alias("max_score")).collect()[0].max_score
    )
    best_model = model_summary.filter(F.col("test_f1") == max_score)
    min_runtime = (
        best_model.select(F.min("runtime").alias("min_runtime"))
        .collect()[0]
        .min_runtime
    )
    best_model = best_model.filter(F.col("runtime") == min_runtime)
    best_model = best_model.select("model").collect()[0].model

best_model = best_model.replace("Classifier", "ClassificationModel")
Model = eval(best_model)

used_cols = [
    c
    for c in dataset.columns
    if c not in exclude_cols + categorical_cols + numerical_cols
]

prediction_result_dict = {}
for target_col in product:
    log.info("%s", target_col)
    assemblerInputs = [c for c in used_cols if c != target_col]
    assembler = VectorAssembler(inputCols=assemblerInputs, outputCol="features")

    data_input = assembler.transform(dataset).select(
        "cif_number", "features", target_col
    )

    model_path = getConfig("prediction", "model_fpath", sc) + "_" + target_col
    model = Model.load(model_path)

    prediction_result = model.transform(data_input)
    prediction_result = prediction_result.select(
        "cif_number", target_col, "probability", "prediction"
    )
    prediction_result = prediction_result.withColumn(
        "probability", get_probability("probability")
    )
    prediction_result = prediction_result.withColumn(
        target_col, F.col(target_col).cast("double")
    )

    prediction_result_dict[target_col] = prediction_result.select(
        "cif_number", "probability"
    )

for i, target_col in enumerate(product):
    tmp = prediction_result_dict[target_col]
    tmp = tmp.withColumnRenamed("probability", target_col)
    if i == 0:
        prediction = tmp
    else:
        prediction = prediction.join(tmp, on="cif_number", how="inner")

prediction = prediction.groupBy("cif_number").apply(get_recommended_product)

prediction = prediction.withColumn("predict_date", F.lit(today.strftime("%Y-%m-%d")))
writeData(
    prediction, spark, "mldb", "mii_rs_product_recommendation", partition="predict_date"
)

